import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';
import path from 'path';

export default defineConfig({
  plugins: [react()],
  resolve: {
    alias: {
      'reader-core': path.resolve(__dirname, '../../packages/reader-core/src/index.ts')
    },
    dedupe: ['react', 'react-dom']
  },
  optimizeDeps: {
    include: ['react', 'react-dom']
  }
});

/** @type {import('tailwindcss').Config} */
module.exports = {
  content: [
    "./index.html",
    "./src/**/*.{js,ts,jsx,tsx,json}",
    "../../packages/reader-core/src/**/*.{js,ts,jsx,tsx}"
  ],
  darkMode: 'class',
  theme: {
    extend: {
      fontFamily: { sans: ['Inter', 'sans-serif'], serif: ['Merriweather', 'serif'] },
      typography: (theme) => ({
        DEFAULT: { css: { color: theme('colors.gray.800'), h1: { color: theme('colors.gray.900') }, h2: { color: theme('colors.gray.900') }, h3: { color: theme('colors.gray.900') }, strong: { color: theme('colors.gray.900') }, blockquote: { borderLeftColor: theme('colors.indigo.500') } } },
        invert: { css: { color: theme('colors.gray.300'), h1: { color: theme('colors.white') }, h2: { color: theme('colors.gray.100') }, h3: { color: theme('colors.gray.200') }, strong: { color: theme('colors.white') }, blockquote: { borderLeftColor: theme('colors.indigo.400'), color: theme('colors.gray.300') } } }
      }),
      keyframes: {
        'fade-in-up': { '0%': { opacity: '0', transform: 'translateY(10px)' }, '100%': { opacity: '1', transform: 'translateY(0)' } },
        'bounce-in': { '0%': { opacity: '0', transform: 'scale(0.9)' }, '50%': { opacity: '1', transform: 'scale(1.05)' }, '100%': { opacity: '1', transform: 'scale(1)' } }
      },
      animation: { 'fade-in-up': 'fade-in-up 0.3s ease-out', 'bounce-in': 'bounce-in 0.3s cubic-bezier(0.68, -0.55, 0.265, 1.55)' }
    }
  },
  plugins: [require('@tailwindcss/typography')]
};

/** Build from an empty generated directory so packages cannot contain stale declarations or source maps. */
import { rmSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { execFileSync } from 'node:child_process';
const core = resolve(dirname(fileURLToPath(import.meta.url)), '../packages/reader-core');
rmSync(resolve(core, 'dist'), { recursive: true, force: true });
execFileSync(process.execPath, [resolve(core, 'node_modules/typescript/bin/tsc'), '-p', resolve(core, 'tsconfig.json')], { cwd: core, stdio: 'inherit' });

/** Package the original reader CSS and font assets without a runtime CDN. */
import { readFileSync, writeFileSync, mkdirSync, copyFileSync } from 'node:fs';
import { dirname, resolve, basename } from 'node:path';
import { fileURLToPath } from 'node:url';
import { execFileSync } from 'node:child_process';
const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const demo = resolve(root, 'apps/reader-demo');
const output = resolve(root, 'packages/reader-core/dist');
mkdirSync(resolve(output, 'fonts'), { recursive: true });
execFileSync(process.execPath, [resolve(demo, 'node_modules/tailwindcss/lib/cli.js'), '-i', resolve(demo, 'src/index.css'), '-o', resolve(output, 'reader.css'), '-c', resolve(demo, 'tailwind.config.cjs'), '--minify'], { cwd: demo, stdio: 'inherit' });
const fonts = [['inter', ['300', '400', '500', '600', '700']], ['merriweather', ['300', '400', '700', '300-italic']], ['material-symbols-outlined', ['400']]];
let fontCSS = '';
const originalCSS = readFileSync(resolve(root, 'packages/reader-core/src/original/reader-original.css'), 'utf8');
for (const [family, faces] of fonts) {
  const source = resolve(demo, `node_modules/@fontsource/${family}`);
  for (const face of faces) {
    fontCSS += readFileSync(resolve(source, `${face}.css`), 'utf8').replace(/url\((\.\/files\/[^)]+)\)/g, (_, path) => {
      copyFileSync(resolve(source, path), resolve(output, 'fonts', basename(path)));
      return `url(./fonts/${basename(path)})`;
    });
  }
  copyFileSync(resolve(source, 'LICENSE'), resolve(output, 'fonts', `LICENSE-${family}.txt`));
}
writeFileSync(resolve(output, 'reader.css'), fontCSS + '\n' + originalCSS + '\n' + readFileSync(resolve(output, 'reader.css'), 'utf8'));
console.log('Packaged original reader styling, fonts, icons and font licences.');
